<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\ShippingMethod;
use App\Models\ShippingRate;
use Illuminate\Http\{RedirectResponse,Request};
use Illuminate\View\View;
class ShippingMethodController extends Controller {
 public function index(): View { return view('admin.shipping-methods.index',['methods'=>ShippingMethod::with('rates')->withCount('rates')->orderBy('sort_order')->get()]); }
 public function store(Request $r): RedirectResponse { $data=$r->validate(['code'=>'required|alpha_dash|max:40|unique:shipping_methods,code','name'=>'required|string|max:120','description'=>'nullable|string','base_fee_toman'=>'required|integer|min:0','estimated_delivery'=>'nullable|string|max:120','sort_order'=>'required|integer|min:0','is_enabled'=>'nullable|boolean','free_shipping_eligible'=>'nullable|boolean']); $data['is_enabled']=$r->boolean('is_enabled'); $data['free_shipping_eligible']=$r->boolean('free_shipping_eligible'); ShippingMethod::create($data); return back()->with('status','روش ارسال ایجاد شد.'); }
 public function update(Request $r, ShippingMethod $shippingMethod): RedirectResponse { $data=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string','base_fee_toman'=>'required|integer|min:0','estimated_delivery'=>'nullable|string|max:120','sort_order'=>'required|integer|min:0','is_enabled'=>'nullable|boolean','free_shipping_eligible'=>'nullable|boolean']); $data['is_enabled']=$r->boolean('is_enabled'); $data['free_shipping_eligible']=$r->boolean('free_shipping_eligible'); $shippingMethod->update($data); return back()->with('status','روش ارسال به‌روزرسانی شد.'); }
 public function storeRate(Request $r, ShippingMethod $shippingMethod): RedirectResponse { $data=$this->rateData($r); $this->assertNoAmbiguousRule($shippingMethod,$data); $rate=$shippingMethod->rates()->create($data); $this->audit('created',$rate,null,$rate->toArray()); return back()->with('status','قاعده نرخ ذخیره شد.'); }
 public function updateRate(Request $r, ShippingRate $shippingRate): RedirectResponse { $data=$this->rateData($r); $this->assertNoAmbiguousRule($shippingRate->method,$data,$shippingRate->id); $before=$shippingRate->toArray();$shippingRate->update($data);$this->audit('updated',$shippingRate,$before,$shippingRate->fresh()->toArray());return back()->with('status','قاعده نرخ به‌روزرسانی شد.'); }
 public function destroyRate(ShippingRate $shippingRate): RedirectResponse { $before=$shippingRate->toArray();$this->audit('deleted',$shippingRate,$before,null);$shippingRate->delete();return back()->with('status','قاعده نرخ حذف شد.'); }
 public function previewRate(Request $r, ShippingMethod $shippingMethod) { $data=$r->validate(['subtotal_toman'=>'required|integer|min:0','weight_grams'=>'required|integer|min:0','province_code'=>'nullable|string','city_code'=>'nullable|string']);return response()->json(app(\App\Services\ShippingRateService::class)->selected($data['subtotal_toman'],$data['weight_grams'],$data,$shippingMethod->code)); }
 private function rateData(Request $r): array { $data=$r->validate(['province_code'=>'nullable|string|max:20','city_code'=>'nullable|string|max:40','fee_toman'=>'required|integer|min:0','free_over_toman'=>'nullable|integer|min:0','weight_surcharge_toman'=>'nullable|integer|min:0','weight_step_grams'=>'nullable|integer|min:1','min_weight_grams'=>'nullable|integer|min:0','max_weight_grams'=>'nullable|integer|min:0','min_order_toman'=>'nullable|integer|min:0','max_order_toman'=>'nullable|integer|min:0','priority'=>'required|integer|min:0|max:10000','effective_from'=>'nullable|date','effective_until'=>'nullable|date|after_or_equal:effective_from','is_enabled'=>'nullable|boolean']);$data['is_enabled']=$r->boolean('is_enabled');if(isset($data['max_weight_grams'],$data['min_weight_grams'])&&$data['max_weight_grams']<$data['min_weight_grams'])abort(422,'حداکثر وزن باید بزرگ‌تر یا مساوی حداقل وزن باشد.');if(isset($data['max_order_toman'],$data['min_order_toman'])&&$data['max_order_toman']<$data['min_order_toman'])abort(422,'حداکثر مبلغ باید بزرگ‌تر یا مساوی حداقل مبلغ باشد.');return $data; }
 private function assertNoAmbiguousRule(ShippingMethod $method,array $data,?int $ignore=null): void { $exists=$method->rates()->where('is_enabled',true)->when($ignore,fn($q)=>$q->where('id','!=',$ignore))->where('province_code',$data['province_code']??null)->where('city_code',$data['city_code']??null)->where('priority',$data['priority'])->exists();if($exists)abort(422,'قاعده فعال هم‌سطح برای این محدوده و اولویت وجود دارد.'); }
 private function audit(string $action,ShippingRate $rate,?array $before,?array $after): void { \DB::table('shipping_configuration_audits')->insert(['user_id'=>request()->user()?->id,'subject_type'=>ShippingRate::class,'subject_id'=>$rate->id,'action'=>$action,'before'=>$before?json_encode($before):null,'after'=>$after?json_encode($after):null,'created_at'=>now(),'updated_at'=>now()]); }
}
